import numpy as np, math
# distance from point to any cell in valid component(s), metric L1/L2/Chebyshev
def marker_sets(arr,col,min_size=3):
 return [g for g in color_comps(arr,col) if len(g)>=min_size]
def metric_preds(arr,out,base,targets,min_size=3,metric='manhattan'):
 H,W=len(arr),len(arr[0]); groups={co:marker_sets(arr,co,min_size) for co in targets}
 def distpoint(p,q):
  dr=abs(p[0]-q[0]);dc=abs(p[1]-q[1])
  if metric=='manhattan':return dr+dc
  if metric=='euclidean':return dr*dr+dc*dc
  if metric=='chebyshev':return max(dr,dc)
 rows=[]
 for r in range(H):
  for c in range(W):
   if arr[r][c]==base:
    ds={co:min((distpoint((r,c),p) for g in groups[co] for p in g),default=999) for co in targets}
    md=min(ds.values());near=[co for co,v in ds.items() if v==md]
    pred=base if len(near)>1 else near[0]
    rows.append((r,c,ds,pred,out[r][c]))
 return rows
