 for metric in ('manhattan','euclidean','chebyshev'):
  rows=metric_preds(arr,out,base,cols,3,metric)
  ms=[x for x in rows if x[3]!=x[4]]
  print(name,metric,'mismatches',len(ms),'example',ms[:10])

